from pathlib import Path
import hashlib
import json
root = Path('products/services/open-software-tenders')
for path in sorted(root.rglob('*.json')):
    if path.stat().st_size > 1048576:
        continue
    try:
        raw = path.read_bytes()
        data = json.loads(raw)
    except (ValueError, OSError):
        continue
    if not isinstance(data, dict):
        continue
    records = data.get('records') or []
    releases = list(data.get('releases') or [])
    for record in records:
        if isinstance(record, dict):
            releases.extend(record.get('releases') or [])
    rows = []
    for release in releases:
        if not isinstance(release, dict):
            continue
        tender = release.get('tender') or {}
        if not isinstance(tender, dict):
            continue
        period = tender.get('tenderPeriod') or {}
        rows.append({'ocid': release.get('ocid'), 'id': release.get('id'), 'date': release.get('date'), 'tags': release.get('tag'), 'status': tender.get('status'), 'deadline': period.get('endDate') if isinstance(period, dict) else None})
    if rows or any(word in str(path).lower() for word in ('amend', 'comparison', 'verdict')):
        print(json.dumps({'path': str(path), 'sha256': hashlib.sha256(raw).hexdigest(), 'release_count': len(rows), 'releases': rows[:12], 'keys': sorted(data)[:18]}, ensure_ascii=True))
